     9	    @Test
    10	    void testRoundToCentsHalfEven() {
    11	        assertEquals(new BigDecimal("3.00"), CurrencyUtils.roundToCents(new BigDecimal("2.995")));
    12	        assertEquals(new BigDecimal("2.98"), CurrencyUtils.roundToCents(new BigDecimal("2.985")));
    13	        assertEquals(new BigDecimal("2.50"), CurrencyUtils.roundToCents(new BigDecimal("2.505")));
    14	    }
    15	
    16	    @Test
    17	    void testMultiply() {
    18	        BigDecimal result = CurrencyUtils.multiply(new BigDecimal("79.90"), new BigDecimal("2"));
    19	        assertEquals(new BigDecimal("159.80"), result);
    20	    }
    21	
    22	    @Test
    23	    void testAdd() {
    24	        BigDecimal result = CurrencyUtils.add(new BigDecimal("79.90"), new BigDecimal("20.00"));
    25	        assertEquals(new BigDecimal("99.90"), result);
    26	    }
    27	
    28	    @Test
    29	    void testDivide() {
    30	        BigDecimal result = CurrencyUtils.divide(new BigDecimal("100.00"), new BigDecimal("3"));
    31	        assertEquals(new BigDecimal("33.33"), result);
    32	    }
    33	
    34	    @Test
    35	    void testSubtract() {
    36	        BigDecimal result = CurrencyUtils.subtract(new BigDecimal("100.00"), new BigDecimal("30.00"));
    37	        assertEquals(new BigDecimal("70.00"), result);
    38	    }
    39	}
