495	@Service
496	@RequiredArgsConstructor
497	public class TransLogClient {
498	    @Value("${translog.url:http://localhost:8081}")
499	    private String translogUrl;
500	
501	    private final ObjectMapper objectMapper;
502	
503	    public Optional<TransLogQuoteResponse> getQuote(String zipCode, Integer weightGrams, String service) {
504	        try {
505	            String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s",
506	                    translogUrl, zipCode, weightGrams, service);
507	
508	            HttpClient httpClient = HttpClient.newBuilder()
509	                    .connectTimeout(Duration.ofSeconds(2))
510	                    .build();
511	
512	            HttpRequest request = HttpRequest.newBuilder()
513	                    .uri(URI.create(url))
514	                    .timeout(Duration.ofSeconds(2))
515	                    .GET()
516	                    .build();
517	
518	            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
519	
520	            if (response.statusCode() == 200) {
521	                @SuppressWarnings("unchecked")
522	                Map<String, Object> responseBody = objectMapper.readValue(response.body(), Map.class);
523	
524	                if (responseBody.containsKey("error")) {
525	                    if ("ZIP_NOT_SERVED".equals(responseBody.get("error"))) {
526	                        return Optional.empty();
527	                    }
528	                    return Optional.empty();
529	                }
530	
531	                Integer priceCents = ((Number) responseBody.get("price_cents")).intValue();
532	                Integer etaHours = ((Number) responseBody.get("eta_hours")).intValue();
533	
534	                return Optional.of(TransLogQuoteResponse.builder()
535	                        .priceCents(priceCents)
536	                        .etaHours(etaHours)
537	                        .build());
538	            }
539	
540	            return Optional.empty();
541	        } catch (IOException | InterruptedException e) {
542	            return Optional.empty();
543	        }
544	    }
545	
546	    @lombok.Data
547	    @lombok.NoArgsConstructor
548	    @lombok.AllArgsConstructor
549	    @lombok.Builder
550	    public static class TransLogQuoteResponse {
551	        private Integer priceCents;
552	        private Integer etaHours;
553	    }
554	}

