421	
422	    public static BigDecimal roundToCents(BigDecimal value) {
423	        if (value == null) {
424	            return BigDecimal.ZERO;
425	        }
426	        return value.setScale(2, ROUNDING_MODE);
427	    }
428	
429	    public static BigDecimal multiply(BigDecimal a, BigDecimal b) {
430	        return roundToCents(a.multiply(b));
431	    }
432	
433	    public static BigDecimal divide(BigDecimal a, BigDecimal b) {
434	        return roundToCents(a.divide(b, 10, ROUNDING_MODE));
435	    }
436	
437	    public static BigDecimal add(BigDecimal... values) {
438	        BigDecimal result = BigDecimal.ZERO;
439	        for (BigDecimal value : values) {
440	            if (value != null) {
441	                result = result.add(value);
442	            }
443	        }
444	        return roundToCents(result);
445	    }
